// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// 1) Pega os clientes (vieram do Colab pelo Webhook) e os investimentos (do node "Investimentos")
const entrada = $input.first().json;
const clientes = entrada.body?.clientes ?? $('Webhook').first().json.body.clientes ?? [];
const investimentos = entrada.investimentos ?? $('Investimentos').first().json.investimentos ?? [];

// Transforma "R$ 12.500,00" em 12500
function paraNumero(texto) {
  const limpo = String(texto).replace(/[^\d,]/g, "").replace(",", ".");
  return Number(limpo) || 0;
}

// Formata 1000 como "R$ 1.000,00"
function paraReais(valor) {
  return valor.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

// Escolhe uma mensagem aleatória da lista
function pick(lista) {
  return lista[Math.floor(Math.random() * lista.length)];
}

// 2) Para cada cliente, escolhe o investimento do perfil dele
const resultados = clientes.map(c => {
  const nome = c.nome;
  const email = c.email;
  const perfil = c.perfil;
  const saldoNum = paraNumero(c.saldo);

  // Opções do mesmo perfil, da menor para a maior aplicação mínima
  const opcoes = investimentos
    .filter(i => String(i.perfil).toLowerCase() === String(perfil).toLowerCase())
    .sort((a, b) => a.minimo - b.minimo);

  // Opções que o saldo do cliente já cobre
  const cabeNoSaldo = opcoes.filter(i => i.minimo <= saldoNum);

  let escolhido = null;
  let motivo = "sem_opcao_para_perfil";
  if (cabeNoSaldo.length > 0) {
    escolhido = cabeNoSaldo[cabeNoSaldo.length - 1]; // a mais completa que cabe no saldo
    motivo = "saldo_ok";
  } else if (opcoes.length > 0) {
    escolhido = opcoes[0]; // a de menor mínimo, para ele juntar até lá
    motivo = "saldo_insuficiente";
  }

  // 3) Monta as mensagens para o cliente
  let mensagens = [];
  if (escolhido && motivo === "saldo_ok") {
    const p = escolhido.produto, m = paraReais(escolhido.minimo), r = escolhido.rentabilidade;
    mensagens = [
      `Olá ${nome}! Pelo seu perfil (${perfil}), uma boa opção é **${p}** (mínimo ${m}). Com seu saldo atual (${c.saldo}), você já consegue investir. Rentabilidade: ${r}.`,
      `Oi ${nome}! Recomendação para perfil ${perfil}: **${p}** (mínimo ${m}). Seu saldo (${c.saldo}) já atende o mínimo. Rentabilidade: ${r}.`,
      `${nome}, indo direto ao ponto: para o perfil ${perfil}, **${p}** (mínimo ${m}). Você tem ${c.saldo}, então dá pra aplicar. Rentabilidade: ${r}.`,
    ];
  } else if (escolhido) {
    const p = escolhido.produto, m = paraReais(escolhido.minimo), falta = paraReais(escolhido.minimo - saldoNum);
    mensagens = [
      `Olá ${nome}! Para o seu perfil (${perfil}), a opção de entrada é **${p}** (mínimo ${m}). Faltam ${falta} para você começar.`,
      `Oi ${nome}! Seu saldo (${c.saldo}) ainda não cobre o mínimo de **${p}** (${m}). Juntando mais ${falta}, você já pode investir.`,
    ];
  } else {
    mensagens = [`Olá ${nome}! No momento não temos opções cadastradas para o perfil ${perfil}.`];
  }

  return {
    nome,
    email,
    perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens),
  };
});

// 4) Devolve tudo junto para o Respond to Webhook
return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados,
  }
}];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

