// Nome do node que preparou os e-mails (um item por cliente).
// Se o seu tiver outro nome, troque aqui.
const NODE_EMAILS = "Code in JavaScript";

// Pega o texto que a IA respondeu (funciona com os formatos do node OpenAI)
function pegarTexto(j) {
  return (
    j?.output?.[0]?.content?.[0]?.text ??
    j?.message?.content ??
    j?.choices?.[0]?.message?.content ??
    j?.text ??
    j?.content ??
    ""
  );
}

// A IA costuma responder com ```json ... ```. Aqui limpamos e abrimos o JSON.
function lerJSON(texto) {
  let t = String(texto).trim();
  t = t.replace(/^```(?:json)?\s*/i, "").replace(/```\s*$/, "").trim();
  const ini = t.indexOf("{");
  const fim = t.lastIndexOf("}");
  if (ini >= 0 && fim > ini) t = t.slice(ini, fim + 1);
  try {
    return JSON.parse(t);
  } catch (e) {
    return null;
  }
}

const clientes = $(NODE_EMAILS).all();

return $input.all().map((item, i) => {
  const j = clientes[i]?.json ?? {};   // dados do cliente na mesma posição
  const email = lerJSON(pegarTexto(item.json));

  const subject = email?.subject ?? "";
  const text_body = email?.text_body ?? "";
  const html_body = email?.html_body ?? "";
  const to = j.email_to ?? j.email ?? "";

  return {
    json: {
      ok: Boolean(email && to),
      to,
      subject,
      text_body,
      html_body,

      // (opcional) manter alguns campos úteis pra debug/aula
      meta: {
        nome: j.nome,
        perfil: j.perfil,
        produto: j.recomendacao?.produto,
        minimo: j.recomendacao?.minimo,
        rentabilidade: j.recomendacao?.rentabilidade,
        motivo: j.motivo
      }
    }
  };
});
